import {T,studio,platform,loadVehicle,vehicles} from './automotive.js';
export async function startVehicleStage(){
 const host=document.querySelector('#vehicle-stage'),root=document.querySelector('.private-showroom'),status=document.querySelector('#model-status'),toggle=document.querySelector('#rotate-toggle');const reduced=matchMedia('(prefers-reduced-motion: reduce)');
 let view;try{view=await studio(host)}catch(error){status.textContent='3D unavailable on this device. Vehicle photography and reservations remain available.';throw error}
 const {scene,camera,renderer}=view,turntable=platform(scene),models=new Map();let current=null,category=null,request=0,booking=false,paused=reduced.matches,drag=false,lastX=0,quietUntil=0,speed=0,last=performance.now(),zoom=1,transition=0;
 document.querySelector('#reset-view').addEventListener('click',()=>{turntable.rotation.y=-.55;zoom=1;quietUntil=performance.now()+5000});
 function updateToggle(){toggle.textContent=paused?'Resume rotation':'Pause rotation';toggle.setAttribute('aria-pressed',String(paused))}updateToggle();toggle.addEventListener('click',()=>{paused=!paused;updateToggle()});reduced.addEventListener('change',()=>{paused=reduced.matches;updateToggle()});
 host.addEventListener('pointerdown',e=>{drag=true;lastX=e.clientX;quietUntil=performance.now()+5000;host.setPointerCapture(e.pointerId)});host.addEventListener('pointermove',e=>{if(!drag)return;turntable.rotation.y+=(e.clientX-lastX)*.006;lastX=e.clientX;quietUntil=performance.now()+5000});host.addEventListener('pointerup',()=>drag=false);host.addEventListener('pointercancel',()=>drag=false);host.addEventListener('wheel',e=>{e.preventDefault();zoom=T.MathUtils.clamp(zoom+e.deltaY*.0004,.78,1.3);quietUntil=performance.now()+3000},{passive:false});host.tabIndex=0;host.setAttribute('role','img');host.setAttribute('aria-label','3D vehicle on a rotating turntable. Drag to rotate, or use left and right arrow keys.');host.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();turntable.rotation.y+=e.key==='ArrowLeft'?-.12:.12;quietUntil=performance.now()+5000}});
 async function select(next){if(next===category)return;category=next;const token=++request;status.hidden=false;status.textContent=`Loading ${vehicles[next].name}…`;try{let model=models.get(next);if(!model){model=await loadVehicle(next);models.set(next,model)}if(token!==request)return;root.classList.add('switching-model');await new Promise(resolve=>setTimeout(resolve,reduced.matches?0:350));if(token!==request)return;if(current)turntable.remove(current);current=model;const platformScale=next==='Sprinter'?1:.84;turntable.children[0].scale.set(platformScale,1,platformScale);turntable.children[1].scale.set(platformScale,platformScale,1);root.classList.remove('switching-model');model.position.y+=model.userData.raised?0:.105;model.userData.raised=true;turntable.add(model);turntable.rotation.y=-.55;root.classList.add('model-ready');status.hidden=true;document.querySelector('#photo-index').textContent=vehicles[next].name.toUpperCase();}catch(error){root.classList.remove('model-ready');status.textContent='This 3D vehicle is unavailable. Reservations remain available.';console.error(error)}}
 function frame(now){const dt=Math.min((now-last)/1000,.04);last=now;if(!document.hidden){const target=(!paused&&!booking&&!drag&&now>quietUntil)?Math.PI*2/60:0;speed=T.MathUtils.damp(speed,target,3,dt);turntable.rotation.y+=speed*dt;transition=reduced.matches?(booking?1:0):T.MathUtils.damp(transition,booking?1:0,3,dt);const mobile=matchMedia('(max-width:760px)').matches,distance=(mobile?1.7:(category==='Sprinter'?1.12:1))*zoom;camera.fov=mobile?48:34;camera.updateProjectionMatrix();camera.position.set((6.6-transition*1.2)*distance,(category==='Sprinter'?3.6:2.5)*distance,(8-transition*1.5)*distance);camera.lookAt(transition*1.4,category==='Sprinter'?1.45:.9,0);renderer.render(scene,camera)}raf=requestAnimationFrame(frame)}let raf=requestAnimationFrame(frame);addEventListener('pagehide',()=>{cancelAnimationFrame(raf);view.dispose()},{once:true});
 return {select,book(value){booking=value},pause(){paused=true;updateToggle()}};
}





